<script setup lang="ts">
import {computed,onMounted,onUnmounted,reactive,ref,watch} from 'vue'
import {api,hasDesktop,type Item,type Page,type State,type Bucket,type BackupPreview,type History,type Filter} from './api'
import BackupHistory from './components/BackupHistory.vue'
import BackupExportDialog from './components/BackupExportDialog.vue'
import BackupLoadDialog from './components/BackupLoadDialog.vue'
import MediaDeleteDialog from './components/MediaDeleteDialog.vue'
import {useMediaManager} from './useMediaManager'
const historyPage=ref(false),exportFilter=ref<Filter|null>(null),loadPreview=ref<BackupPreview|null>(null)
const state=ref<State>({phase:'idle',mode:'source',source:null,sources:[],scanned:0,bytes:0,report:null,watching:false,coverage:'',revision:0,error:'',message:'',backup:null,excluded:0,cached:false,last_full_scan:'',reconcile_seconds:120,index_bytes:0})
const page=ref<Page>({items:[],total:0,bytes:0,baseline_files:0}),buckets=ref<Bucket[]>([])
const year=ref('')
const kind=ref(''),month=ref(''),role=ref(''),status=ref(''),size=ref(''),offset=ref(0),view=ref('source'),from=ref(''),to=ref('')
const includeBaseline=ref(false),querying=ref(false)
const error=ref(''),notice=ref(''),action=ref(false),desktop=ref(hasDesktop()),listing=ref(false),selected=ref<Item|null>(null)
const mediaURL=ref(''),playError=ref(false),history=ref<History[]>([]),failed=ref(new Set<string>()),renaming=ref(false),sourceName=ref('')
let timer:ReturnType<typeof setInterval>|undefined,polling=false,generation=0,disposed=false
const busy=computed(()=>action.value||['backup','verifying','discovering','restoring','deleting','preparing_delete','recycling'].includes(state.value.phase))
const scanning=computed(()=>state.value.phase==='scanning')
const restoreIssues=computed(()=>state.value.restore?.placements.filter(p=>p.error)??[])
const kinds=[{id:'image',name:'图片',symbol:'▧'},{id:'video',name:'视频',symbol:'▷'},{id:'emoji',name:'收到的表情',symbol:'☺'},{id:'voice',name:'语音',symbol:'≋'}]
const roles:Record<string,string>={original:'原件',preview:'缩略图',cover:'视频封面',temporary:'临时资源',unknown:'角色未知'}
const statuses:Record<string,string>={recognized:'已识别文件头',unknown:'未知格式',empty:'零字节',invalid_header:'文件头损坏或不支持',unreadable:'无法读取',changed:'扫描时发生变化'}
const methods:Record<string,string>={baseline:'扫描前已存在',live_event:'监控中首次发现',rescan_after_gap:'中断或核对扫描后发现',user_reported:'用户标注'}
const issues:Record<string,string>={directory_limit:'达到目录上限',directory_unreadable_or_link:'目录不可读或含链接',link_skipped:'已跳过链接',stat_failed:'无法读取文件信息',non_regular_skipped:'已跳过特殊文件',file_limit:'达到文件上限',unreadable:'无法读取',changed:'扫描期间发生变化',directory_read_failed:'目录未完整读取'}
const eventNames:Record<string,string>={seen:'首次记录',stable:'通过稳定性检查',superseded:'被新版本替换',rename:'文件位置变化',missing:'核对时缺失',user_recycled:'用户移至回收站'}
const fmtTime=(v:string|null|undefined)=>v&&!v.startsWith('0001-')?new Date(v).toLocaleString():'未知'
const bytes=(v:number)=>{if(!v)return '0 B';const u=['B','KiB','MiB','GiB','TiB'];const i=Math.min(4,Math.floor(Math.log(v)/Math.log(1024)));return `${(v/1024**i).toFixed(i?1:0)} ${u[i]}`}
const name=(i:Item)=>i.relative_path.split('/').at(-1)??i.relative_path
const kindName=(id:string)=>kinds.find(k=>k.id===id)?.name??id
const symbol=(id:string)=>kinds.find(k=>k.id===id)?.symbol??'▧'
const sourceLabel=(s:{name:string;root:string})=>{const parts=s.root.split(String.fromCharCode(92)).join('/').split('/');const at=parts.map(p=>p.toLowerCase()).lastIndexOf('nt_data');const account=at>=2&&parts[at-1].toLowerCase()==='nt_qq'?parts[at-2]:'';return account&&s.name!==account?`${s.name} · ${account}`:s.name}
const thumb=(i:Item)=>`/media/thumbnail/${encodeURIComponent(i.id)}`
const failPreview=(id:string)=>{failed.value=new Set([...failed.value,id])}
const title=computed(()=>month.value?`${month.value==='__unknown__'?'月份未知':month.value} · ${kind.value?kindName(kind.value):'全部类型'}`:kind.value?kindName(kind.value):'全部类型')
const years=computed(()=>[...new Set(buckets.value.filter(b=>!kind.value||b.kind===kind.value).map(b=>b.month.slice(0,4)).filter(y=>/^\d{4}$/.test(y)))].sort().reverse())
const months=computed(()=>{const m=new Map<string,number>();for(const b of buckets.value){if(kind.value&&b.kind!==kind.value)continue;if(year.value&&!b.month.startsWith(year.value+'-'))continue;m.set(b.month,(m.get(b.month)??0)+b.files)}return [...m].sort(([a],[b])=>b.localeCompare(a))})
const totals=computed(()=>kinds.map(k=>{const bs=(state.value.report?.buckets??[]).filter(b=>b.kind===k.id);return {...k,files:bs.reduce((s,b)=>s+b.files,0),bytes:bs.reduce((s,b)=>s+b.bytes,0)}}))
function filter():Filter{return {include_baseline:includeBaseline.value,kind:kind.value,month:month.value,month_from:year.value?year.value+'-01':'',month_to:year.value?year.value+'-12':'',role:role.value,status:status.value,min_bytes:Number(size.value)||0,max_bytes:0,offset:offset.value,limit:60,view:view.value,from:from.value,to:to.value}}
async function load(){const id=++generation;const source=state.value.source?.id;querying.value=true;if(from.value&&to.value&&from.value>to.value){error.value='开始日期不能晚于结束日期';querying.value=false;return}error.value='';try{const [p,bs]=await Promise.all([api().GetPage(filter()),api().GetFilterBuckets(filter())]);if(id===generation&&!disposed&&source===state.value.source?.id){page.value=p;buckets.value=bs}}catch(e){error.value=String(e)}finally{if(id===generation)querying.value=false}}
function selectYear(){month.value='';from.value='';to.value=''};
function selectMonth(value:string){month.value=value;if(value&&value!=='__unknown__')year.value=value.slice(0,4);else if(value==='__unknown__')year.value='';if(view.value==='observed'){from.value='';to.value=''}}
function queryDate(){year.value='';month.value='';offset.value=0;void load()}
function resetFilters(){year.value='';kind.value='';month.value='';from.value='';to.value='';role.value='';status.value='';size.value='';offset.value=0;void load()}
function showInitialImport(){includeBaseline.value=true;offset.value=0}
async function poll(){if(polling||!hasDesktop()||disposed)return;polling=true;try{const revision=state.value.revision;state.value=await api().GetState();if(revision!==state.value.revision)await load();void api().UIReady()}catch(e){error.value=String(e)}finally{polling=false}}
async function run(fn:()=>Promise<unknown>){action.value=true;generation++;error.value='';notice.value='';try{await fn();state.value=await api().GetState();await load()}catch(e){error.value=String(e)}finally{action.value=false}}
const manager=reactive(useMediaManager(state,busy,filter,run))
const selectedCount=computed(()=>manager.all?Math.max(0,page.value.total-manager.excludedCount):manager.manualCount)
const choose=()=>run(async()=>{const path=await api().ChooseSource();if(path){historyPage.value=false;year.value='';failed.value=new Set();selected.value=null;month.value='';offset.value=0}})
const start=(mode:string)=>run(async()=>{failed.value=new Set();await api().StartUpdate(mode)})
const stopping=ref(false)
async function terminateUpdate(){stopping.value=true;try{await run(()=>api().StopUpdate())}finally{stopping.value=false}}
const cancel=()=>run(()=>api().CancelScan())
const openBackup=(expectedID='')=>run(async()=>{const preview=await api().ChooseBackup(expectedID);if(preview)loadPreview.value=preview})
const loadHistory=(id:string)=>run(async()=>{loadPreview.value=await api().PreviewHistoryBackup(id)})
const viewLoaded=(id:string)=>run(async()=>{await api().ViewLoadedBackup(id);historyPage.value=false;year.value='';failed.value=new Set();selected.value=null;view.value='source';month.value='';from.value='';to.value='';offset.value=0})
const removeBackups=(ids:string[])=>run(()=>api().DeleteBackups(ids))
async function confirmLoad(id:string,target:string){loadPreview.value=null;await run(async()=>{await api().LoadBackup(id,target);historyPage.value=false;year.value='';failed.value=new Set();selected.value=null;view.value='source';month.value='';from.value='';to.value='';offset.value=0})}
const switchSource=(event:Event)=>{const id=(event.target as HTMLSelectElement).value;if(id)void run(async()=>{await api().SwitchSource(id);historyPage.value=false;year.value='';failed.value=new Set();selected.value=null;month.value='';offset.value=0})}
const backupError=ref(''),backupSubmitting=ref(false)
function prepareBackup(){backupError.value='';exportFilter.value={...filter(),offset:0}}
async function backup(f:Filter,format:string,path:string){backupSubmitting.value=true;action.value=true;backupError.value='';try{await api().CreateBackupAt(f,format,path);exportFilter.value=null;state.value=await api().GetState();await load()}catch(e){backupError.value=String(e)}finally{backupSubmitting.value=false;action.value=false}}
async function exportIndex(){await run(async()=>{const path=await api().ExportIndex();if(path)notice.value=`观察索引已备份：${path}`})}
async function rename(){await run(()=>api().RenameSource(sourceName.value));renaming.value=false}
async function inspect(item:Item){selected.value=item;mediaURL.value='';playError.value=false;history.value=[];try{const h=await api().GetHistory(item.id);if(selected.value?.id===item.id)history.value=h}catch{};if(item.format==='iso-bmff'||item.preview){try{const url=await api().GetMediaURL(item.id);if(selected.value?.id===item.id)mediaURL.value=url}catch{playError.value=true}}}
function closeDetail(){selected.value=null;mediaURL.value='';history.value=[]}
function onKey(e:KeyboardEvent){if(e.key==='Escape'){closeDetail();manager.dialog=null;if(!backupSubmitting.value)exportFilter.value=null;loadPreview.value=null;renaming.value=false}}
watch([year,kind,month,role,status,size,view,from,to,includeBaseline],()=>{offset.value=0;if(desktop.value)void load()})
watch(view,()=>{year.value='';month.value='';from.value='';to.value=''})
watch([from,to],()=>{if(view.value==='observed'&&(from.value||to.value)){month.value='';year.value=''}})
watch(includeBaseline,()=>{month.value=''})
watch(offset,()=>{void load()})
onMounted(()=>{desktop.value=hasDesktop();void poll();timer=setInterval(()=>void poll(),800);window.addEventListener('keydown',onKey)})
onUnmounted(()=>{disposed=true;if(timer)clearInterval(timer);window.removeEventListener('keydown',onKey)})
</script>

<template>
<div class="shell">
 <aside class="sidebar">
  <div class="brand"><span class="brand-icon">Q</span><div>Qman<small>QQ 本地媒体管理</small></div></div>
  <div class="nav-label">账号 / 媒体来源</div>
  <select class="source-select" aria-label="切换媒体来源" :value="state.mode==='source'?state.source?.id:''" :disabled="busy" @change="switchSource"><option value="" disabled>切换账号 / 媒体来源</option><option v-for="s in state.sources" :key="s.id" :value="s.id" :title="s.root">{{sourceLabel(s)}}</option></select>
  <button class="add-source" :disabled="!desktop||busy" @click="choose">选择 QQ 数据文件夹</button>
  <div class="nav-label">媒体库</div>
  <button class="nav-item" :class="{active:!historyPage&&!kind}" @click="historyPage=false;kind='';month=''">▦ <span>全部类型</span><em>{{state.report?.files??'—'}}</em></button>
  <button v-for="k in kinds" :key="k.id" class="nav-item" :class="{active:!historyPage&&kind===k.id}" @click="historyPage=false;kind=k.id;month=''">{{k.symbol}} <span>{{k.name}}</span></button>
  <button class="nav-item" :class="{active:historyPage}" @click="historyPage=true"><span>备份历史</span></button><div v-if="!historyPage" class="nav-label month-heading">{{view==='observed'?'发现月份':'来源月份'}} <span>{{months.length}}</span></div>
  <div v-if="!historyPage" class="month-list"><button class="month-item" :class="{active:!month}" @click="selectMonth('')">全部月份</button><button v-for="[m,count] in months" :key="m" class="month-item" :class="{active:month===(m||'__unknown__')}" @click="selectMonth(m||'__unknown__')">{{m||'来源月份未知'}}<span>{{count}}</span></button><p v-if="!months.length" class="sidebar-hint">{{view==='observed'&&!includeBaseline?'首次导入旧文件默认不计新增，可勾选包含首次导入记录。':'建立索引后可按月份查看。'}}</p></div>
  <div class="sidebar-footer"><span class="privacy-dot"></span>本机处理 · 按需恢复媒体<small>0.3.4 · 快速与全盘更新</small></div>
 </aside>
 <main>
  <header class="topbar"><span>我的媒体库 <span class="breadcrumb">/ {{historyPage?'备份历史':state.mode==='backup'?'独立备份':title}}</span></span><div class="header-actions"><button :disabled="!desktop||busy" @click="openBackup()">加载备份</button><button :disabled="!desktop||busy" @click="exportIndex">备份观察索引</button></div></header>
  <div class="workspace">
   <div v-if="historyPage"><div v-if="error||state.error" class="notice error" role="alert">{{error||state.error}}</div><div v-if="state.message" class="notice success" role="status">{{state.message}}</div><div v-if="busy" class="scan-progress" role="status">正在处理所选任务 · {{state.scanned}} 项<button v-if="scanning" :disabled="stopping||state.stopping" @click="terminateUpdate">{{stopping||state.stopping?'正在终止…':'终止更新'}}</button><button v-else @click="cancel">取消任务</button></div><BackupHistory :busy="busy" @load="loadHistory" @relocate="openBackup" @view="viewLoaded" @remove="removeBackups" @clean="manager.prepareBackups" @clean-results="manager.results"/></div>
   <template v-else>
   <div class="page-heading"><div><div class="eyebrow">LOCAL MEDIA LIBRARY</div><h1>{{year&&!month?year+' 年 · ':''}}{{title}}</h1><p>按月份查找，让本地媒体井然有序。</p></div><button class="primary" :disabled="!desktop||busy" @click="choose">选择 QQ 数据文件夹</button></div>
   <p class="folder-help">可选择最外层 QQ 数据目录（如 Tencent Files）导入媒体清单，自动识别其中账号；也支持账号目录或 nt_data。原文件保持原位。</p>
   <div v-if="!desktop" class="notice">请使用 Qman 桌面程序管理本地媒体。浏览器预览不读取本机目录。</div>
   <div v-if="error||state.error" class="notice error" role="alert">{{error||state.error}}</div>
   <div v-if="notice||state.message" class="notice success" role="status">{{notice||state.message}}<p v-if="state.backup">{{state.backup.path}}<br/>{{state.backup.files}} 个文件，{{state.backup.unique_objects}} 个唯一对象，{{state.backup.excluded}} 项未纳入（原因保存在清单）。</p></div>
   <section v-if="!state.source" class="empty-card"><div class="folder-art"><svg viewBox="0 0 140 110" aria-hidden="true"><path d="M19 28h40l12 13h53v55H19z" fill="#b9dace"/><path d="M17 40h110l-13 58H28z" fill="#d8ebe3"/><rect x="48" y="16" width="47" height="55" rx="6" fill="#fff" stroke="#9bbdad"/><path d="m53 58 12-14 10 9 9-13 6 18z" fill="#64a68e"/><circle cx="62" cy="31" r="5" fill="#c4ddbc"/><path d="M17 53h110l-13 45H28z" fill="#b4d6c7"/></svg></div><h2>从 QQ 文件夹开始</h2><p>可选择最外层 QQ 数据目录（如 Tencent Files）导入媒体清单，自动识别其中的账号。<br/>也支持账号目录或 nt_data；不复制、移动原文件。</p><button class="primary" :disabled="!desktop||busy" @click="choose">选择 QQ 数据文件夹</button><div class="empty-notes"><span>✓ 无需登录 QQ</span><span>✓ 添加来源只读</span><span>✓ 不上传媒体</span></div></section>
   <template v-else>
    <div v-if="state.discovery" class="discovery-summary">已发现 {{state.discovery.candidates.length}} 个账号 / 媒体来源，未扫描其他账号的媒体内容。<br/>检索范围：{{state.discovery.root}}<span v-if="state.discovery.linked">（已解析所选链接）</span><span v-if="!state.discovery.complete"> · 存在跳过项或达到发现边界</span></div>
    <section class="source-panel"><div class="source-icon">▱</div><div class="source-details"><strong>{{state.mode==='backup'?'已验证的独立备份':state.source.name}}</strong><button v-if="state.mode==='source'" class="text-button" @click="renaming=!renaming;sourceName=state.source.name">重命名来源</button><p :title="state.source.resolved">{{state.source.resolved}}</p><small v-if="state.source.linked">上方为解析后的真实路径，请核对后再扫描。</small><div v-if="renaming" class="rename-row"><input v-model="sourceName" maxlength="60" aria-label="来源名称"/><button class="secondary" @click="rename">保存名称</button></div></div><template v-if="state.mode==='source'"><button v-if="scanning||state.watching||state.background_stage" class="secondary" :disabled="busy||stopping||state.stopping" @click="terminateUpdate" title="停止当前更新及后续监控，保留已有索引">{{stopping||state.stopping?'正在终止…':'终止更新'}}</button><button class="primary" :disabled="busy||scanning" @click="start('fast')" title="沿用旧清单，轻量发现新文件，并监控变化路径">快速更新</button><button class="secondary" :disabled="busy||scanning" @click="start('full')" title="完整核对当前来源全部受支持媒体的新增、变化和缺失，不扫描其他账号或整块磁盘">全盘更新</button></template></section>
    <div v-if="scanning||['backup','verifying','discovering','restoring','deleting','preparing_delete','recycling'].includes(state.phase)" class="scan-progress" role="status"><div class="indeterminate"></div><span>{{state.phase==='backup'?'正在复制并校验备份':state.phase==='verifying'?'正在独立校验备份':state.phase==='discovering'?'正在发现账号目录':state.phase==='restoring'?'正在加载与补回媒体':state.phase==='deleting'?'正在删除备份':state.phase==='preparing_delete'?'正在核对删除清单':state.phase==='recycling'?'正在移至回收站':state.update_mode==='full'?'正在全盘核对当前来源':'正在快速补新'}} · {{state.scanned.toLocaleString()}} 项 · {{bytes(state.bytes)}}</span><button v-if="scanning" :disabled="stopping||state.stopping" @click="terminateUpdate">{{stopping||state.stopping?'正在终止…':'终止更新'}}</button><button v-else @click="cancel">取消任务</button></div>
    <div v-if="state.background_stage" class="monitor-line" role="status">{{state.background_stage==='stability'?'后台：检查待稳定文件':state.background_stage==='changes'?'后台：核对变化路径':'后台：定期查找新文件'}} · 可继续浏览和筛选</div><div v-if="state.coverage" class="monitor-line"><span :class="['privacy-dot',{stopped:!state.watching}]"></span>{{state.coverage}}<span v-if="state.watching">稳定性检查需要至少三次观察，不代表 QQ 确认下载完成。</span></div>
    <div class="stats-grid"><button v-for="t in totals" :key="t.id" class="stat-card" :class="{chosen:kind===t.id}" @click="historyPage=false;kind=kind===t.id?'':t.id;month=''"><span class="stat-symbol">{{t.symbol}}</span><span class="stat-copy">{{t.name}}<strong>{{state.report?bytes(t.bytes):'—'}}</strong><small>{{state.report?t.files.toLocaleString():'—'}} 个文件</small></span></button></div>
    <template v-if="state.report">
     <div v-if="state.mode==='source'" class="cache-summary"><strong>{{state.cached?'本地索引已加载':state.report.update_kind==='full'?'全盘核对已完成':state.report.update_kind==='targeted'?'变化路径已核对':'快速更新已完成'}}</strong><span>上次全盘核对：{{fmtTime(state.last_full_scan)}} · 每 2 分钟快速补新 · 索引 {{bytes(state.index_bytes)}}</span><span v-if="!state.cached">沿用未核对旧记录 {{state.report.known_skipped??0}} 项 · 本轮实际检查 {{state.report.inspected??0}} 项 · 更新 {{state.report.indexed_updates}} 项</span><small v-if="state.cached">当前是上次保存的清单；源断开或文件变化时，预览仍需能读取原文件。</small><small v-else-if="state.report.quick">快速更新未全面核对旧文件的变化和缺失，需要时手动全盘更新；预览、备份、删除前仍检查实际文件。</small></div><div v-if="state.mode==='source'&&state.needs_full" class="notice">发现监听或扫描覆盖缺口。可继续快速补新，建议手动全盘更新；不会自动启动全量扫描。</div>
     <div class="scan-note" :class="{warning:!state.report.complete}"><span>{{state.cached?'已载入本地索引，源文件尚未核对':state.report.complete?(state.report.update_kind==='fast'?'已完成目录补新，旧记录尚未全面核对':state.report.partial?'受影响路径已增量更新':'全盘核对已完成'):'核对存在缺口，保留已有索引'}}</span><span>{{fmtTime(state.report.finished_at)}} · {{state.report.issue_count}} 项扫描问题</span></div>
     <section class="library-panel">
      <div class="library-toolbar"><div class="tabs"><button :class="{active:view==='source'}" @click="view='source'">来源月份</button><select class="month-select" :aria-label="view==='source'?'来源年份选择':'发现年份选择'" v-model="year" @change="selectYear"><option value="">全部年份</option><option v-for="y in years" :key="y" :value="y">{{y}} 年</option></select><select class="month-select" :aria-label="view==='source'?'来源月份选择':'发现月份选择'" :value="month" @change="selectMonth(($event.target as HTMLSelectElement).value)"><option value="">{{view==='source'?'全部来源月份':'全部发现月份'}}</option><option v-for="[m,count] in months" :key="m" :value="m||'__unknown__'">{{m||'月份未知'}}（{{count}}）</option></select><button :class="{active:view==='observed'}" @click="view='observed'">新增发现日期</button></div><div v-if="state.mode==='source'" class="library-actions"><button class="secondary" :class="{chosen:manager.active}" :disabled="busy" @click="manager.toggle">{{manager.active?'完成管理':'管理'}}</button><button class="primary" :disabled="busy||manager.active" @click="prepareBackup">备份当前筛选</button></div><span v-else class="backup-label">已校验 · {{state.excluded}} 项未加载媒体</span></div>
      <form v-if="view==='observed'" class="datebar" @submit.prevent="queryDate"><label>首次发现日期 <input type="date" v-model="from" aria-label="开始日期"/> — <input type="date" v-model="to" aria-label="结束日期"/></label><button class="secondary" type="submit" :disabled="querying">查询</button><button class="text-button" type="button" @click="resetFilters">清空筛选</button><label class="baseline-toggle"><input type="checkbox" v-model="includeBaseline"/>包含首次导入记录</label><span>{{querying?'正在筛选…':'日期更改后自动筛选，也可点击查询。'}} 包含结束日，不代表发送或下载时间。</span></form>
      <div v-if="view==='observed'" class="observation-note">{{includeBaseline?'已包含首次导入时就存在的文件，日期表示首次建立索引的时间；这些文件仍保留“扫描前已存在”标记。':'默认仅显示首次扫描之后发现的文件；昨天首次导入的旧文件可能需要勾选“包含首次导入记录”。'}}<span v-if="page.baseline_files&&!includeBaseline"> 当前条件另有 {{page.baseline_files.toLocaleString()}} 条首次导入记录。</span></div>
      <div class="filterbar"><select aria-label="来源角色" v-model="role"><option value="">全部角色</option><option v-for="(label,value) in roles" :key="value" :value="value">{{label}}</option></select><select aria-label="文件状态" v-model="status"><option value="">全部状态</option><option v-for="(label,value) in statuses" :key="value" :value="value">{{label}}</option></select><select aria-label="最小文件大小" v-model="size"><option value="">全部大小</option><option value="1048576">至少 1 MiB</option><option value="10485760">至少 10 MiB</option><option value="104857600">至少 100 MiB</option></select><div class="view-toggle"><button :class="{chosen:!listing}" @click="listing=false" aria-label="网格视图">▦</button><button :class="{chosen:listing}" @click="listing=true" aria-label="列表视图">☷</button></div></div>
      <div v-if="manager.active" class="manage-toolbar"><span>已选择 {{selectedCount.toLocaleString()}} 个{{manager.all?'（当前筛选，跨页）':''}}</span><button class="secondary" :disabled="busy||!page.items.length" @click="manager.selectPage(page.items)">{{manager.pageSelected(page.items)?'取消本页':'选择本页'}}</button><button class="secondary" :disabled="busy||!page.total" @click="manager.selectAll">选择全部匹配结果</button><button class="text-button" :disabled="busy" @click="manager.clear">清空选择</button><button class="danger-button" :disabled="busy||!selectedCount" @click="manager.prepare">删除（{{selectedCount}}）</button></div><div class="result-caption">{{page.total.toLocaleString()}} 个文件 · 逻辑大小 {{bytes(page.bytes)}}<span>包含原件、预览、临时资源，不是可释放空间</span></div>
      <div v-if="querying" class="query-indicator" role="status">正在更新筛选结果…</div>
      <div v-if="!page.items.length&&!querying" class="no-results"><template v-if="view==='observed'&&!includeBaseline&&page.baseline_files"><p>此条件下的 {{page.baseline_files.toLocaleString()}} 个文件属于首次导入时已有的记录，默认不列为后续新增。</p><button class="secondary" @click="showInitialImport">查看首次导入记录</button></template><template v-else><p>没有符合当前条件的文件。</p><p v-if="view==='observed'">请核对日期、月份和其他筛选；首次导入的旧文件可通过上方选项查看。</p><button class="secondary" @click="resetFilters">清空筛选</button></template></div>
      <div v-else class="media-grid" :class="{listing}"><div v-for="item in page.items" :key="item.id" class="media-entry" :class="{selected:manager.active&&manager.isSelected(item)}"><button class="media-card" @click="manager.active?manager.select(item):inspect(item)"><div class="media-preview"><img v-if="item.preview&&!failed.has(item.id)" :src="thumb(item)" alt="静态缩略预览" loading="lazy" @error="failPreview(item.id)"/><div v-else class="media-placeholder"><span>{{symbol(item.kind)}}</span><small>{{failed.has(item.id)?'预览失败':item.format==='iso-bmff'?'视频原件 · 点击尝试播放':item.format==='silk'?'SILK · 原文件保留':item.status==='recognized'?'暂不支持预览':statuses[item.status]}}</small></div><span class="role-tag">{{roles[item.role]}}</span></div><div class="media-info"><strong :title="item.relative_path">{{name(item)}}</strong><div><span>{{item.source_month||'月份未知'}} · {{item.format.toUpperCase()}}</span><span>{{bytes(item.bytes)}}</span></div><small :class="['item-state',{pending:item.stability!=='stable_heuristic'}]">{{item.stability==='stable_heuristic'?'通过稳定性检查':'待稳定或不支持'}} · {{methods[item.observation_method]??'时间证据未知'}}</small></div></button><label v-if="manager.active" class="media-check"><input type="checkbox" :aria-label="'选择 '+item.relative_path" :checked="manager.isSelected(item)" :disabled="busy" @change="manager.select(item)"/></label></div></div>
      <div class="pagination"><span>每页最多 60 个文件</span><button class="secondary" :disabled="offset===0" @click="offset=Math.max(0,offset-60)">上一页</button><span>{{Math.floor(offset/60)+1}} / {{Math.max(1,Math.ceil(page.total/60))}}</span><button class="secondary" :disabled="offset+60>=page.total" @click="offset+=60">下一页</button></div>
     </section>
     <details v-if="state.report.issue_count" class="issues"><summary>扫描问题（{{state.report.issue_count}}，最多展示 1000 项）</summary><div v-for="(issue,i) in state.report.issues" :key="i"><code>{{issue.path}}</code><span>{{issues[issue.code]??issue.code}}</span></div></details>
    </template>
    <div v-else-if="!scanning" class="ready-note">账号来源已选择，尚无索引。可先快速更新建立清单；首次读取仍需识别新文件，之后旧文件可沿用。全盘更新核对当前来源的全部受支持媒体。</div>
   </template>
   <details v-if="restoreIssues.length" class="issues"><summary>加载项目说明</summary><div v-for="(item,i) in restoreIssues" :key="i"><code>{{item.relative_path}}</code><span>{{item.status==='fallback'?'已独立保存：':'未完成：'}}{{item.error}}</span></div></details>
   <details v-if="state.excluded_items?.length" class="issues"><summary>未加载或未包含的媒体项目（{{state.excluded_items.length}}）</summary><div v-for="(item,i) in state.excluded_items" :key="i"><code>{{item.path}}</code><span>{{statuses[item.code]??({temporary:'临时资源',pending:'尚未稳定'} as Record<string,string>)[item.code]??item.code}}</span></div></details>
   <button v-if="state.cleanup" class="secondary cleanup-result-button" :disabled="busy" @click="manager.results()">查看最近删除任务</button><footer class="workspace-footer">来源月份是文件夹标签，不代表发送月或下载月。备份是复制，不减少源占用。语音仅盘点与原文件备份。</footer></template>
  </div>
 </main>
 <div v-if="selected" class="modal-backdrop" @click.self="closeDetail"><section class="detail-modal" role="dialog" aria-modal="true" aria-label="媒体详情"><button class="close-modal" @click="closeDetail" aria-label="关闭详情">×</button><div class="detail-preview"><video v-if="mediaURL&&selected.format==='iso-bmff'&&!playError" :src="mediaURL" controls preload="metadata" @error="playError=true"></video><img v-else-if="mediaURL&&!playError" :src="mediaURL" alt="媒体预览" @error="playError=true"/><span v-else>{{playError?'此文件当前无法预览；可能缺少对应编码支持。':'此格式暂不支持内置预览，原文件已保留。'}}</span></div><h2>{{name(selected)}}</h2><dl><dt>源相对路径</dt><dd>{{selected.relative_path}}</dd><dt>类型 / 来源角色</dt><dd>{{kindName(selected.kind)}} / {{roles[selected.role]}}</dd><dt>来源月份</dt><dd>{{selected.source_month||'未知'}}</dd><dt>逻辑大小 / 格式</dt><dd>{{bytes(selected.bytes)}} / {{selected.format}} · {{statuses[selected.status]}}</dd><dt>首次发现</dt><dd>{{fmtTime(selected.first_seen_at)}} · {{methods[selected.observation_method]??'未知'}}</dd><dt>稳定观察时间</dt><dd>{{fmtTime(selected.stable_observed_at)}}</dd><dt>文件系统创建时间</dt><dd>{{fmtTime(selected.fs_created_at)}}</dd><dt>文件系统修改时间</dt><dd>{{fmtTime(selected.fs_modified_at)}}</dd></dl><details v-if="history.length" class="history"><summary>查看已保存的观察记录（{{history.length}}）</summary><p v-for="(h,i) in history" :key="i">{{fmtTime(h.at)}} · {{eventNames[h.kind]??h.kind}}</p></details><p>首次发现是本工具的观察证据，不是 QQ 下载时间；稳定和文件头识别也不证明完整下载。原件、封面和临时文件分别管理。</p></section></div>
 <MediaDeleteDialog v-if="manager.dialog" :job="manager.dialog" :busy="busy" :read-only="manager.dialogReadOnly" @close="manager.dialog=null" @confirm="manager.execute"/><BackupExportDialog v-if="exportFilter" :initial="exportFilter" :submitting="backupSubmitting" :submit-error="backupError" :monitoring="state.watching||state.update_running" @close="exportFilter=null" @confirm="backup"/>
 <BackupLoadDialog v-if="loadPreview" :preview="loadPreview" @close="loadPreview=null" @confirm="confirmLoad"/>
</div>
</template>
